def extract_format(format, extra_types):
    '''Pull apart the format [[fill]align][0][width][.precision][type[base]]
    '''
    fill = align = None
    if format[0] in '<>=^':
        align = format[0]
        format = format[1:]
    elif len(format) > 1 and format[1] in '<>=^':
        fill = format[0]
        align = format[1]
        format = format[2:]

    zero = False
    if format and format[0] == '0':
        zero = True
        format = format[1:]

    width = ''
    while format:
        if not format[0].isdigit():
            break
        width += format[0]
        format = format[1:]

    if format.startswith('.'):
        # Precision isn't needed but we need to capture it so that
        # the ValueError isn't raised.
        format = format[1:]  # drop the '.'
        precision = ''
        while format:
            if not format[0].isdigit():
                break
            precision += format[0]
            format = format[1:]

    # the rest is the type, if present - may include base for b/o/x types
    # e.g., 'b2', 'o8', 'x16' where digits after type are the base
    base = None
    type = format
    if type:
        # Check if type starts with a base-type char followed by digits (the base)
        if type[0] in 'box' and len(type) > 1 and type[1:].isdigit():
            base = int(type[1:])
            type = type[0]
        elif type[0] in 'box':
            base = None  # auto-detect based on prefix
        elif type not in ALLOWED_TYPES and type not in extra_types:
            raise ValueError('format spec %r not recognised' % type)

    return locals()

